  const target = path.join(path.dirname(filename), 'screenpack.lua');
  const next = setSectionEntry(document, files.line, 'module', 'screenpack.lua');
  reauthorize();
  if (liveDocument(filename)?.isDirty) throw new Error('Save or discard the native DEF changes before atomically creating and assigning its Lua module.');
