function screenpackCompactLayoutStyle(){return `
  .app{min-width:0;min-height:0}
  .screenpack-companion{min-width:0;min-height:0;background:var(--panel);border-left:1px solid var(--line)}
  .screenpack-companion .side{border-left:0;border-right:0;border-bottom:1px solid var(--line)}
  .screenpack-companion #screenpackBrowserNote{display:none}
  #screenpackFlow{margin-top:9px}
  .flow-list{display:grid;gap:2px}
  .flow-row{display:grid;grid-template-columns:minmax(0,1fr);gap:3px;padding:7px 0;border-top:1px solid var(--line)}
  .flow-row>b,.flow-row>span{display:block;min-width:0;overflow-wrap:anywhere;line-height:1.35}
  .flow-row>span{color:var(--muted)}
  .flow-actions{display:flex;flex-wrap:wrap;gap:4px;margin-top:2px}
  .flow-menu-row{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:3px 6px;padding:5px 0;border-top:1px solid var(--line)}
  .flow-menu-row>span{min-width:0;overflow-wrap:anywhere}
  .flow-menu-row>.flow-actions{grid-column:1/-1}
  @media(min-width:721px){
    body{overflow:hidden}
    .app{height:100vh;grid-template-columns:minmax(0,1fr) clamp(290px,29vw,390px);grid-template-rows:auto minmax(0,1fr) auto;overflow:hidden}
    .toolbar{grid-column:1/-1;grid-row:1}
    .viewport{grid-column:1;grid-row:2;min-height:0}
    .screenpack-companion{grid-column:2;grid-row:2;display:block;overflow:auto}
    .screenpack-companion .left,.screenpack-companion .right{grid-row:auto;max-height:none;overflow:visible}
    .status{grid-column:1/-1;grid-row:3}
  }
  @media(max-width:720px){
    .app{height:auto;grid-template-columns:minmax(0,1fr);grid-template-rows:auto 340px auto auto;overflow:auto}
    .toolbar{grid-column:1;grid-row:1}
    .viewport{grid-column:1;grid-row:2;min-height:340px}
    .screenpack-companion{grid-column:1;grid-row:3;display:block;overflow:visible;border-left:0}
    .screenpack-companion .left,.screenpack-companion .right{grid-row:auto;max-height:none;overflow:visible}
    .status{grid-column:1;grid-row:4;white-space:normal;overflow-wrap:anywhere}
  }
  .screenpack-companion-open #screenpackElementHeading,.screenpack-companion-open .browser-controls,.screenpack-companion-open #elements{display:none}
  .screenpack-companion-open #screenpackBrowserNote{display:block!important}
`}

