function screenpackPreviewControlAvailability(input={}){
  const hasItem=Boolean(input.hasItem),locked=Boolean(input.locked),hasOverride=Boolean(input.hasOverride),gridMode=Boolean(input.gridMode),gridValid=input.gridValid!==false,gridChanged=Boolean(input.gridChanged);
  const selectionReason='Add or select a screenpack element to enable this action.',lockReason='Unlock every selected element before editing or applying its preview position.',changeReason='Move the selected element before applying or discarding a preview position.';
  return Object.freeze({
    copy:Object.freeze({disabled:!hasItem,reason:hasItem?'':'Add or select a screenpack element before copying its position patch.'}),
    position:Object.freeze({disabled:!hasItem||locked,reason:!hasItem?selectionReason:locked?lockReason:''}),
    apply:Object.freeze({disabled:!hasItem||locked||!hasOverride,reason:!hasItem?selectionReason:locked?lockReason:!hasOverride?changeReason:''}),
    discard:Object.freeze({disabled:!hasItem||!hasOverride,reason:!hasItem?selectionReason:!hasOverride?'There is no preview position change to discard.':''}),
    grid:Object.freeze({disabled:!gridMode||!gridValid||!gridChanged,reason:!gridMode?'Open Character Select Layout Builder to edit the grid.':!gridValid?'Rows, columns, cell width, and cell height must be positive numbers.':!gridChanged?'Change at least one grid value before reviewing the layout.':''})
  });
}
